INSERT INTO action_guides (hazard, phase, min_level, targets, priority, title, content, voice_text, source_name, source_url) VALUES
  ('heavy_rain', 'during', 'advisory', '{all}', 10, '호우가 시작되면', '신속히 안전한 곳으로 대피하고 외출을 삼갑니다. 이웃·가족과 연락해 안전 여부를 확인합니다.', '비가 많이 오고 있습니다. 외출을 삼가고 안전한 곳에 머무르세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'advisory', '{all}', 20, '호우주의보 발령 시', '저지대·상습침수지역 등 재해위험지구 주민은 대피를 준비합니다. 노후가옥·위험축대를 점검하고, 고압전선에 접근하지 않으며 옥내·외 전기수리를 하지 않습니다. 뇌우 시 저지대 또는 인근 가옥으로 대피합니다. 배수문과 양수기를 점검합니다.', '호우주의보입니다. 저지대 주민은 대피를 준비하고, 축대와 전선 가까이 가지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'advisory', '{fisher,vessel_owner,coastal}', 25, '호우주의보 발령 시 (해안지역)', '수산 증·양식 시설물을 보호하고, 해안저지대 위험지역 경계를 강화하며 주민은 안전지대 대피를 준비합니다.', '양식 시설을 점검하고, 해안 저지대에서는 대피를 준비하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'advisory', '{farmer}', 40, '호우주의보 발령 시 (농촌지역)', '농작물·농축산을 보호하고 용·배수로와 소하천, 봇물, 둑을 정비합니다. 산간계곡 야영객은 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'warning', '{all}', 5, '호우경보 발령 시', '저지대·상습침수지역 등 재해위험지구 주민은 대피합니다. 노후가옥·위험축대에 접근하지 않고, 옥내·외 전기설비 고장 시 수리하지 않습니다. 낙뢰·뇌우 시 위험시설물을 미리 제거하고, 홍수에 대비해 저지대 주민은 대피합니다.', '호우경보입니다. 저지대와 침수 위험 지역 주민은 지금 대피하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'warning', '{fisher,vessel_owner,coastal}', 6, '호우경보 발령 시 (해안지역)', '해안저지대 주민은 경계를 강화하고 안전지대로 대피합니다. 대피 선박은 다른 선박과 충돌하지 않도록 고무타이어를 달고 로프로 안전지대에 결박합니다.', '배는 고무타이어를 달고 로프로 단단히 묶은 뒤, 해안 저지대에서 벗어나세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('heavy_rain', 'during', 'warning', '{farmer}', 30, '호우경보 발령 시 (농촌지역)', '농작물 보호와 농축산시설 보강, 용·배수로 정비, 논둑 보수와 물꼬 조정을 합니다. 소규모 교량은 안전을 확인한 후 이용하고, 낙석·붕괴 위험지구에는 접근하지 않습니다. 산간계곡 야영객은 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010000'),
  ('typhoon', 'before', 'watch', '{all}', 10, '태풍이 예보되면', '거주 지역에 영향을 주는 시기를 미리 파악해 이웃과 공유하고, 어떻게 대피할지 가족·주변 사람과 함께 준비합니다.', '태풍이 다가오고 있습니다. 대피 장소와 방법을 가족과 미리 정해 두세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'advisory', '{all}', 10, '태풍이 시작되면', '이웃과 함께 신속히 안전한 곳으로 대피하고 외출을 삼갑니다. 가족·이웃에게 연락해 안전을 확인하고 위험 상황을 알립니다.', '태풍 영향권입니다. 외출하지 말고 안전한 곳에 머무르세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'advisory', '{all}', 20, '태풍주의보 발령 시', '저지대·상습침수지역 주민은 대피를 준비합니다. 지붕을 결박하고 떨어질 위험이 있는 시설물은 제거하거나 묶습니다. 고압전선에 접근하지 않고 전기수리를 하지 않으며, 송전철탑이 넘어지거나 누전·방전을 발견하면 인근 기관이나 한전에 알립니다. 출입문·창문은 굳게 닫아 잠그고, 노약자·어린이는 외출하지 않습니다.', '태풍주의보입니다. 창문을 닫아 잠그고, 날아갈 물건은 치우거나 묶어 두세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'advisory', '{fisher,vessel_owner,coastal}', 15, '태풍주의보 발령 시 (해안지역)', '해안저지대 주민은 경계를 강화하고 안전지대로 대피합니다. 대피 선박은 다른 선박과 충돌하지 않도록 고무타이어를 달고 로프로 안전지대에 결박합니다.', '배를 고무타이어와 로프로 단단히 묶고, 해안 저지대에서 벗어나세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'advisory', '{farmer}', 40, '태풍주의보 발령 시 (농촌지역)', '농작물·농촌시설을 보호·보강하고 용·배수로, 소하천, 간이 취입보를 점검합니다. 산간계곡 야영객은 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'warning', '{all}', 5, '태풍경보 발령 시', '지붕을 결박하고 떨어질 위험이 있는 시설물은 제거하거나 묶습니다. 고압송전시설과 송전철탑 주변에 가지 않고 전기수리를 하지 않습니다. 출입문·창문은 굳게 닫아 잠그고, 노약자·어린이는 외출하지 않습니다.', '태풍경보입니다. 밖에 나가지 말고, 창문을 잠근 채 실내에 머무르세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'warning', '{fisher,vessel_owner,coastal}', 4, '태풍경보 발령 시 (어업인·해안지역)', '선박은 안전하게 결박하거나 육지로 끌어올려(양육) 대피합니다. 어망 부설을 중지하고 철거하며, 옮길 수 있는 증식시설은 안전지대로 이전합니다.', '태풍경보입니다. 배를 육지로 올리거나 단단히 묶고, 부두에는 가지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('typhoon', 'during', 'warning', '{farmer}', 30, '태풍경보 발령 시 (농촌지역)', '농작물·농촌시설을 보호·보강하고 비닐하우스 등 농림시설을 보호합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010200'),
  ('strong_wind', 'during', 'advisory', '{all}', 20, '강풍·풍랑 특보 시', 'TV·라디오로 강풍·풍랑 정보와 관공서의 재난 예·경보를 수시로 확인합니다. 야외활동을 자제하고 주변 독거노인 등 건강이 염려되는 분의 안부를 살핍니다.', '바람이 강합니다. 야외활동을 자제하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('high_seas', 'during', 'advisory', '{all}', 20, '강풍·풍랑 특보 시', 'TV·라디오로 강풍·풍랑 정보와 관공서의 재난 예·경보를 수시로 확인합니다. 야외활동을 자제하고 주변 독거노인 등 건강이 염려되는 분의 안부를 살핍니다.', '바람이 강합니다. 야외활동을 자제하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('strong_wind', 'during', 'warning', '{all}', 10, '강풍경보 발령 시', '간판 등 부착물을 고정·결박합니다. 고가·위험담장에 접근하지 않고, 옥내·외 전기설비 고장 시 수리하지 않습니다.', '강풍경보입니다. 간판과 담장 근처를 피하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('strong_wind', 'during', 'warning', '{farmer}', 30, '강풍경보 발령 시 (농촌지역)', '특용작물 등 농작물과 비닐하우스 보호 조치를 강화하고 농촌시설을 보강합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('high_seas', 'during', 'warning', '{fisher,vessel_owner,coastal}', 5, '강풍·풍랑경보 발령 시 (어업인)', '선박 출항을 금지하고, 선박은 육지로 끌어올리거나(양육) 결박합니다. 철거 가능한 어로시설은 철거하고, 옮길 수 있는 증식시설은 안전지대로 이전합니다.', '풍랑경보입니다. 출항하지 말고, 배를 육지로 올리거나 단단히 묶어 두세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('strong_wind', 'during', 'warning', '{fisher,vessel_owner,coastal}', 5, '강풍·풍랑경보 발령 시 (어업인)', '선박 출항을 금지하고, 선박은 육지로 끌어올리거나(양육) 결박합니다. 철거 가능한 어로시설은 철거하고, 옮길 수 있는 증식시설은 안전지대로 이전합니다.', '풍랑경보입니다. 출항하지 말고, 배를 육지로 올리거나 단단히 묶어 두세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301010300'),
  ('heavy_rain', 'during', 'watch', '{all}', 30, '호우·태풍이 올 때 (가정)', '라디오·TV로 기상상황을 계속 확인하고, 축대·담장이 무너질 염려나 바람에 날아갈 물건이 없는지 다시 확인합니다. 긴급 대피를 준비하고 이웃·행정기관 연락망을 확인하며, 노약자·어린이는 외출을 삼갑니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{all}', 30, '호우·태풍이 올 때 (가정)', '라디오·TV로 기상상황을 계속 확인하고, 축대·담장이 무너질 염려나 바람에 날아갈 물건이 없는지 다시 확인합니다. 긴급 대피를 준비하고 이웃·행정기관 연락망을 확인하며, 노약자·어린이는 외출을 삼갑니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{all}', 25, '호우·태풍이 올 때 (보행자)', '천둥·번개가 칠 때는 우산을 쓰지 말고 전신주·큰 나무 밑을 피해 낮은 곳이나 큰 건물 안으로 대피합니다. 물에 잠긴 도로는 피하고, 작은 개울이라도 건너지 말고 안전한 도로를 이용합니다.', '물에 잠긴 길과 개울은 건너지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{all}', 25, '호우·태풍이 올 때 (보행자)', '천둥·번개가 칠 때는 우산을 쓰지 말고 전신주·큰 나무 밑을 피해 낮은 곳이나 큰 건물 안으로 대피합니다. 물에 잠긴 도로는 피하고, 작은 개울이라도 건너지 말고 안전한 도로를 이용합니다.', '물에 잠긴 길과 개울은 건너지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('flood', 'during', 'watch', '{all}', 25, '호우·태풍이 올 때 (보행자)', '천둥·번개가 칠 때는 우산을 쓰지 말고 전신주·큰 나무 밑을 피해 낮은 곳이나 큰 건물 안으로 대피합니다. 물에 잠긴 도로는 피하고, 작은 개울이라도 건너지 말고 안전한 도로를 이용합니다.', '물에 잠긴 길과 개울은 건너지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{driver}', 25, '호우·태풍이 올 때 (차량 운행)', '물에 잠긴 도로나 잠수교를 피해 평소 아는 길로 저단기어로 운행합니다. 하천변에 주차한 차량은 신속히 안전한 곳으로 옮깁니다.', '물에 잠긴 도로로 운전하지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{driver}', 25, '호우·태풍이 올 때 (차량 운행)', '물에 잠긴 도로나 잠수교를 피해 평소 아는 길로 저단기어로 운행합니다. 하천변에 주차한 차량은 신속히 안전한 곳으로 옮깁니다.', '물에 잠긴 도로로 운전하지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('flood', 'during', 'watch', '{driver}', 25, '호우·태풍이 올 때 (차량 운행)', '물에 잠긴 도로나 잠수교를 피해 평소 아는 길로 저단기어로 운행합니다. 하천변에 주차한 차량은 신속히 안전한 곳으로 옮깁니다.', '물에 잠긴 도로로 운전하지 마세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{resident}', 20, '호우·태풍이 올 때 (상습침수지역)', '행정기관과 수시로 연락해 권고에 따르고, 비상시에는 지정된 안전한 장소로 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{resident}', 20, '호우·태풍이 올 때 (상습침수지역)', '행정기관과 수시로 연락해 권고에 따르고, 비상시에는 지정된 안전한 장소로 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('flood', 'during', 'watch', '{resident}', 20, '호우·태풍이 올 때 (상습침수지역)', '행정기관과 수시로 연락해 권고에 따르고, 비상시에는 지정된 안전한 장소로 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('landslide', 'during', 'watch', '{all}', 15, '호우·태풍이 올 때 (산간지역·산사태)', '경사도가 30° 이상인 곳은 산사태 우려가 높으므로 미리 안전한 곳으로 대피하고, 비가 그친 뒤에도 계속 주의 깊게 살펴봅니다. 배수로는 깊이 파고, 과수목·비닐하우스는 받침을 보강하고 단단히 묶습니다.', '산비탈 가까이 계시면 지금 안전한 곳으로 대피하세요. 비가 그친 뒤에도 조심하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{all}', 15, '호우·태풍이 올 때 (산간지역·산사태)', '경사도가 30° 이상인 곳은 산사태 우려가 높으므로 미리 안전한 곳으로 대피하고, 비가 그친 뒤에도 계속 주의 깊게 살펴봅니다. 배수로는 깊이 파고, 과수목·비닐하우스는 받침을 보강하고 단단히 묶습니다.', '산비탈 가까이 계시면 지금 안전한 곳으로 대피하세요. 비가 그친 뒤에도 조심하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{fisher,vessel_owner,coastal}', 15, '호우·태풍이 올 때 (어촌·해안)', '선박은 미리 고무타이어를 달고 로프로 안전지대에 결박합니다. 운항 중이면 태풍 이동경로에서 최대한 멀리 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{fisher,vessel_owner,coastal}', 15, '호우·태풍이 올 때 (어촌·해안)', '선박은 미리 고무타이어를 달고 로프로 안전지대에 결박합니다. 운항 중이면 태풍 이동경로에서 최대한 멀리 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('high_seas', 'during', 'watch', '{fisher,vessel_owner,coastal}', 15, '호우·태풍이 올 때 (어촌·해안)', '선박은 미리 고무타이어를 달고 로프로 안전지대에 결박합니다. 운항 중이면 태풍 이동경로에서 최대한 멀리 대피합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('typhoon', 'during', 'watch', '{tourist}', 15, '호우·태풍이 올 때 (해수욕장·낚시터·야영장)', '물건에 미련을 두지 말고 신속히 안전한 장소로 대피합니다.', '바닷가와 낚시터에서 바로 벗어나 안전한 곳으로 이동하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'during', 'watch', '{tourist}', 15, '호우·태풍이 올 때 (해수욕장·낚시터·야영장)', '물건에 미련을 두지 말고 신속히 안전한 장소로 대피합니다.', '바닷가와 낚시터에서 바로 벗어나 안전한 곳으로 이동하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('high_seas', 'during', 'watch', '{tourist}', 15, '호우·태풍이 올 때 (해수욕장·낚시터·야영장)', '물건에 미련을 두지 말고 신속히 안전한 장소로 대피합니다.', '바닷가와 낚시터에서 바로 벗어나 안전한 곳으로 이동하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030000'),
  ('heavy_rain', 'after', 'normal', '{all}', 10, '피해 확인과 신고', '이웃 등 주변 피해 상황을 확인하고, 가까운 행정복지센터에 피해를 신고해 보수·보강합니다. 이재민은 읍면동이 지정한 수용장소로 이동해 구호요원의 안내에 따릅니다.', '피해가 있으면 가까운 행정복지센터에 신고하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('typhoon', 'after', 'normal', '{all}', 10, '피해 확인과 신고', '이웃 등 주변 피해 상황을 확인하고, 가까운 행정복지센터에 피해를 신고해 보수·보강합니다. 이재민은 읍면동이 지정한 수용장소로 이동해 구호요원의 안내에 따릅니다.', '피해가 있으면 가까운 행정복지센터에 신고하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('flood', 'after', 'normal', '{all}', 10, '피해 확인과 신고', '이웃 등 주변 피해 상황을 확인하고, 가까운 행정복지센터에 피해를 신고해 보수·보강합니다. 이재민은 읍면동이 지정한 수용장소로 이동해 구호요원의 안내에 따릅니다.', '피해가 있으면 가까운 행정복지센터에 신고하세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('heavy_rain', 'after', 'normal', '{all}', 15, '침수되었던 집에 들어갈 때', '먼저 창문을 열어 환기한 뒤 들어가고, 전기설비·수도관·가스관을 점검합니다. 필요하면 관계기관에 알려 안전점검을 받습니다.', '침수된 집에는 환기부터 하고, 전기와 가스를 확인한 뒤 들어가세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('typhoon', 'after', 'normal', '{all}', 15, '침수되었던 집에 들어갈 때', '먼저 창문을 열어 환기한 뒤 들어가고, 전기설비·수도관·가스관을 점검합니다. 필요하면 관계기관에 알려 안전점검을 받습니다.', '침수된 집에는 환기부터 하고, 전기와 가스를 확인한 뒤 들어가세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('flood', 'after', 'normal', '{all}', 15, '침수되었던 집에 들어갈 때', '먼저 창문을 열어 환기한 뒤 들어가고, 전기설비·수도관·가스관을 점검합니다. 필요하면 관계기관에 알려 안전점검을 받습니다.', '침수된 집에는 환기부터 하고, 전기와 가스를 확인한 뒤 들어가세요.', '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('heavy_rain', 'after', 'normal', '{fisher,vessel_owner,coastal}', 20, '수산시설물·양식생물 관리', '어장 내 오물과 흙탕물을 빨리 제거하고 신선한 물로 바꿉니다. 파손된 시설물은 즉시 보수하고 질병 여부를 확인합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('typhoon', 'after', 'normal', '{fisher,vessel_owner,coastal}', 20, '수산시설물·양식생물 관리', '어장 내 오물과 흙탕물을 빨리 제거하고 신선한 물로 바꿉니다. 파손된 시설물은 즉시 보수하고 질병 여부를 확인합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('high_seas', 'after', 'normal', '{fisher,vessel_owner,coastal}', 20, '수산시설물·양식생물 관리', '어장 내 오물과 흙탕물을 빨리 제거하고 신선한 물로 바꿉니다. 파손된 시설물은 즉시 보수하고 질병 여부를 확인합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('heavy_rain', 'after', 'normal', '{farmer}', 30, '농작물·가축 관리', '침수된 농작물은 신속히 물을 빼고 쓰러진 작물을 세웁니다. 축사는 소독·환기하고 가축의 수인성 전염병 예방접종을 합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200'),
  ('typhoon', 'after', 'normal', '{farmer}', 30, '농작물·가축 관리', '침수된 농작물은 신속히 물을 빼고 쓰러진 작물을 세웁니다. 축사는 소독·환기하고 가축의 수인성 전염병 예방접종을 합니다.', NULL, '포항시 재난안전 홈페이지', 'https://www.pohang.go.kr/safe/contents.do?mid=0301030200');
INSERT INTO support_programs (category, hazards, targets, name, summary, eligibility, how_to_apply, apply_period, department, contact, url) VALUES
  ('insurance', '{typhoon,heavy_rain,flood,strong_wind,high_seas}', '{resident}', '풍수해·지진재해보험', '태풍·홍수·호우·강풍·풍랑·해일·대설·지진 피해를 보상하는 정책보험. 보험료의 55% 이상을 정부·지자체가 지원. 재난지원금보다 보상이 큼 (예: 주택 침수 시 재난지원금 300만원, 보험금 최대 1,070만원 · 80㎡ 소유자 기준).', '주택, 온실(비닐하우스 포함), 소상공인 상가·공장. 보험료 지원 55%~, 차상위·한부모 78%~, 기초생활수급자 87%~, 재해취약지역 실거주 저소득층 100%', '보험사 또는 읍면동 행정복지센터. 국민재난안전포털 > 정책보험(풍수해보험)', '연중 상시', '포항시 재난관리부서 / 읍면동 행정복지센터', 'DB손보 044-205-5990 · 현대해상 044-205-5991 · 삼성화재 044-205-5992 · KB손보 044-205-5993 · NH손보 044-205-5994 · 한화손보 044-205-5995 · 메리츠 044-205-5996 · 중소기업중앙회 02-6900-3240', 'https://www.pohang.go.kr/safe/contents.do?mid=0400000000'),
  ('fishery', '{typhoon,strong_wind,high_seas}', '{fisher}', '양식수산물재해보험', '태풍(강풍)·해일·풍랑·적조·고수온 등으로 인한 양식수산물·시설물 피해 보상. 순보험료 50%와 운영비 100% 지원.', '넙치·전복·굴·조피볼락·참돔 등 30개 품목과 양식 시설물', 'Sh수협은행', NULL, '해양수산부 / 수협', 'Sh수협은행 1588-4119', 'https://www.pohang.go.kr/safe/contents.do?mid=0405000000'),
  ('insurance', '{typhoon,heavy_rain,strong_wind}', '{farmer}', '농작물재해보험', '자연재해·조수해·화재·병충해(일부) 농작물 피해 보상. 순보험료 50%, 운영비 100% 지원.', '농작물 76개 품목 및 농업용 시설', 'NH농협손해보험 또는 가까운 농·축협', NULL, '농림축산식품부 / 농협손해보험', 'NH농협손해보험 1644-8900', 'https://www.pohang.go.kr/safe/contents.do?mid=0405000000'),
  ('insurance', '{typhoon,heavy_rain,strong_wind}', '{farmer}', '가축재해보험', '자연재해·화재·질병(소) 가축 피해 보상. 위험보험료 50% 지원.', '소·돼지·닭 등 16개 축종 및 가축사육시설', '보험사업자 또는 인근 농·축협', NULL, '농림축산식품부', 'DB손보 1600-0100 · KB손보 1544-0800 · NH손보 1644-9000 · 한화손보 1566-8000 · 메리츠 1566-7711', 'https://www.pohang.go.kr/safe/contents.do?mid=0405000000'),
  ('insurance', '{typhoon,heavy_rain,flood,strong_wind,high_seas,landslide}', '{resident}', '포항시민안전보험 (2026)', '포항시 주민등록 시민 자동 가입(별도 가입 불필요). 자연재해(일사병·열사병·저체온증 포함) 상해사망 2,000만원, 익사사고 사망 등 보장. 보장기간 2026.2.1~2027.1.31. 만 15세 미만 사망보험 제외.', '포항시에 주민등록된 시민', '사고접수 후 구비서류 원본 우편 송부 (시민안전공제 민원센터). 일부 담보는 이메일(lofa@aoneis.com)·팩스(0303-0945-6789) 가능', '보장기간 내 사고', '한국지방재정공제회', '시민안전공제 민원센터 1577-5939', 'https://www.pohang.go.kr/safe/contents.do?mid=0403000000'),
  ('recovery', '{typhoon,heavy_rain,flood,strong_wind,high_seas,landslide}', '{all}', '재난 사망·실종·부상 구호금', '자연재해로 사망·실종 시 2,000만원, 부상 시 장해등급 1~7급 1,000만원 · 8~14급 500만원. 피해사실과 귀책사유 확인 후 지급.', '자연재해 피해자 및 유가족 (부상은 신체장해 14급 이상 진단)', '피해사실 확인 후 지급', NULL, '포항시 / 읍면동', NULL, 'https://www.pohang.go.kr/safe/contents.do?mid=0500000000'),
  ('livelihood', '{typhoon,heavy_rain,flood,landslide}', '{all}', '이재민 응급·장기 구호', '주택 침수·소파·반파·유실 시 응급구호(구호물품). 전파·반파·유실로 장기 구호가 필요하면 구호비 지급 (반파 23일, 전파 53일). 침수 우려로 임시 대피 후 귀가한 경우 제외.', '주택 피해를 입은 실거주 이재민', '읍면동에 피해 신고', NULL, '읍면동 행정복지센터', NULL, 'https://www.pohang.go.kr/safe/contents.do?mid=0500000000'),
  ('recovery', '{typhoon,heavy_rain,flood,landslide}', '{resident}', '세입자 보조', '주택 전파·반파·유실 또는 세입자 방 파손으로 이사해야 하는 경우 300만원 한도 내 실제 세입금 지원.', '피해 주택 세입자', '읍면동에 피해 신고 → 세입 사실 확인 후 별도 신청 없이 지급', NULL, '읍면동 행정복지센터', NULL, 'https://www.pohang.go.kr/safe/contents.do?mid=0500000000'),
  ('livelihood', '{typhoon,heavy_rain,flood,strong_wind,high_seas}', '{fisher,farmer}', '생계지원 (농·어업인)', '농·어·임·축·염업 시설, 농작물, 가축, 어선, 어망·어구, 수산생물 등 주생계수단이 50% 이상 피해를 입은 가구에 가구원 수별 생계비 지원.', '주생계수단 50% 이상 피해 농·어·임·축·염가', '읍면동에 피해 신고 → 소득 조회 후 별도 신청 없이 지급', NULL, '읍면동 행정복지센터', NULL, 'https://www.pohang.go.kr/safe/contents.do?mid=0500000000');
